    <div className="settings-group">{children}</div>
  </section>;
}

export default function SettingsView({ selected, onSelect, onClose, children }: { selected: SettingId; onSelect: (id: SettingId) => void; onClose: () => void; children: ReactNode }) {
  const [query, setQuery] = useState("");
  const searchInput = useRef<HTMLInputElement>(null);
  const itemButtons = useRef<Partial<Record<SettingId, HTMLButtonElement | null>>>({});
  const search = query.trim().toLocaleLowerCase();
  const groups = settingGroups.map((group) => ({ ...group, items: group.items.filter((item) => `${group.label} ${item.label} ${item.description} ${item.accessibleLabel || ""} ${item.keywords || ""}`.toLocaleLowerCase().includes(search)) })).filter((group) => group.items.length > 0);
  const visibleItems = groups.flatMap((group) => group.items);
  const current = settingMetadata[selected];
  const clearSearch = () => { setQuery(""); searchInput.current?.focus(); };
  const activate = (item: SettingItem) => { onSelect(item.id); itemButtons.current[item.id]?.focus(); };
  const navigate = (event: KeyboardEvent<HTMLButtonElement>, id: SettingId) => {
    if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229 || event.altKey || event.ctrlKey || event.metaKey) return;
    const index = visibleItems.findIndex((item) => item.id === id);
    const next = event.key === "ArrowDown" ? (index + 1) % visibleItems.length
      : event.key === "ArrowUp" ? (index - 1 + visibleItems.length) % visibleItems.length
      : event.key === "Home" ? 0 : event.key === "End" ? visibleItems.length - 1 : -1;
    if (next < 0) return;
    event.preventDefault();
    activate(visibleItems[next]);
  };
  return <section className="settings-view" aria-label="设置">
    <nav className="settings-nav" aria-label="设置导航">
      <div className="settings-nav-header"><h1 className="settings-page-title">设置</h1><button type="button" className="settings-back" aria-label="返回对话" title="返回对话" onClick={onClose}><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m10 5-7 7 7 7M3 12h18" /></svg></button></div><div className="settings-search"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" /><path d="m16 16 4 4" /></svg><input ref={searchInput} type="search" aria-label="搜索设置" placeholder="搜索设置" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => {
        if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229) return;
        if (event.key === "Escape") { event.preventDefault(); clearSearch(); }
        else if (event.key === "Enter" && visibleItems.length) { event.preventDefault(); activate(visibleItems[0]); }
      }} />{query && <button type="button" className="settings-search-clear" aria-label="清除设置搜索" title="清除设置搜索" onClick={clearSearch}><svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" aria-hidden="true"><path d="m4 4 8 8m0-8-8 8" /></svg></button>}</div>
      {groups.map((group) => <div className="settings-nav-section" key={group.label}>
        <h2 className="settings-nav-group">{group.label}</h2>
        {group.items.map((item) => <button type="button" key={item.id} ref={(button) => { itemButtons.current[item.id] = button; }} className={`settings-nav-item${selected === item.id ? " active" : ""}`} aria-label={item.accessibleLabel} aria-current={selected === item.id ? "page" : undefined} onKeyDown={(event) => navigate(event, item.id)} onClick={() => onSelect(item.id)}><SettingsIcon id={item.id} /><span>{item.label}</span></button>)}
      </div>)}
      {!groups.length && <div className="settings-search-empty"><p className="notice">未找到匹配的设置</p><button type="button" className="text-button" onClick={clearSearch}>显示全部设置</button></div>}
    </nav>
    <div className="settings-content"><div className="settings-content-inner" data-setting={selected}><header className="settings-content-header"><h1 className="settings-title">{current.label}</h1><p className="sr-only">{current.description}</p></header>{children}</div></div>
  </section>;
}
import { useCallback, useEffect, useRef, useState, type KeyboardEvent, type RefObject } from "react";
import DisclosurePopover from "./DisclosurePopover";

export default function ConversationComposer({ inputRef, value, onChange, onKeyDown, onSend, onConfigure, disabled, sending, workspace, workspaceName, native, model, provider, status, visible, error, requestId, fileChanges, onOpenChanges }: {
  inputRef: RefObject<HTMLTextAreaElement>; value: string; onChange: (value: string) => void;
  onKeyDown: (event: KeyboardEvent<HTMLTextAreaElement>) => void; onSend: () => void;
  onConfigure: (setting: "environment" | "models") => void;
  disabled: boolean; sending: boolean; workspace: string; workspaceName: string; native: boolean;
  model: string; provider: string; status: string; visible: boolean; error: string; requestId?: string;
  fileChanges?: number; onOpenChanges?: () => void;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEffect(() => { if (!visible) setOpen(false); }, [visible]);
  const configure = (setting: "environment" | "models") => { setOpen(false); onConfigure(setting); };
  return <footer className="composer-wrap"><div className="composer-stack">
    {onOpenChanges && typeof fileChanges === "number" && fileChanges > 0 && <div className="composer-changes"><button type="button" title="已加载对话中成功写入的真实文件记录；不代表当前 Git 变更总数。" onClick={onOpenChanges}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d="M4 2.5h5l3 3v8H4v-11Zm5 0v3h3M6 9h4M8 7v4" /></svg>{fileChanges} 个文件已更改</button></div>}
    <div className="composer-context">
      <span title={workspace}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 7h7l2 2h9v10H3V7Zm0 0V5h7l2 2" /></svg><span className="composer-workspace-name">{workspaceName}</span></span>
      <span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><rect x="4" y="4" width="16" height="12" rx="1.5" /><path d="M2 20h20M9 16v4m6-4v4" /></svg>{native ? "本地" : "开发连接"}</span>
    </div>
    <div className="composer">
      <textarea ref={inputRef} value={value} onChange={(event) => onChange(event.target.value)} onKeyDown={onKeyDown} placeholder="给 Router 发送消息…" aria-label="消息内容" />
      <div className="composer-bottom">
        <span className="composer-router" title={status}><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m12 3 7.5 4.5v9L12 21l-7.5-4.5v-9L12 3Z" /><path d="m4.5 7.5 7.5 5 7.5-5M12 12.5V21" /></svg>Router</span>
        <span className="composer-keyboard sr-only">Enter 发送 · Shift + Enter 换行</span>
        <div className="composer-model-anchor">
          <button ref={trigger} type="button" className="composer-model" aria-label="查看 Router 配置" aria-expanded={open} aria-controls="router-model-configuration" title={[provider, model].filter(Boolean).join(" / ")} onClick={() => setOpen((value) => !value)}><span>{model}</span><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m5 6 3 3 3-3" /></svg></button>
          <DisclosurePopover open={open && visible} onClose={close} trigger={trigger} id="router-model-configuration" label="Router 模型配置" className="composer-model-menu">
            <div className="model-menu-current"><span className="model-menu-label">当前 Router</span><strong className="router-model">{model}</strong><span className="router-provider">{provider || "供应商未记录"}</span></div>
            <div className="model-menu-actions"><button type="button" aria-label="环境" onClick={() => configure("environment")}>运行配置<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></button><button type="button" onClick={() => configure("models")}>模型库<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></button></div>
          </DisclosurePopover>
        </div>
        <button className="send-button" aria-label="发送消息" disabled={disabled} onClick={onSend}>{sending ? <span className="loading-spinner" aria-hidden="true" /> : <svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M10 16V4m-5 5 5-5 5 5" /></svg>}</button>
      </div>
    </div>
  </div>{error && <p className="send-error" role="alert">{error} 草稿已保留。请求 ID：<code>{requestId}</code></p>}</footer>;
}

用户消息 = 右对齐气泡：

```css
.message.from-user{ align-items:flex-end; }
.message.from-user .message-body{
  max-width: min(80%, 560px);
  background: var(--color-background-user-message);
  color: var(--color-text-user-message);
  border-radius: var(--radius-2xl);        /* 20px */
  padding: 10px 16px;
}
/* 气泡内不再显示头像 */
.message.from-user .message-avatar{ display:none; }
```

助手消息 = 无气泡：

```css
.message.from-agent .message-body{
  background:none; padding:0; border-radius:0;
  font-size:16px; line-height:24px; font-weight:430;
}
```

两者共同的 `.message-meta`：字号 12，颜色 tertiary；**默认 `opacity:0`，`.message:hover` 时 `opacity:1`**（真机就是这样，操作条靠悬停才出现）。

```css
.message .message-meta{ opacity:0; transition:opacity .15s; font-size:12px; color:var(--app-color-text-foreground-tertiary); }
.message:hover .message-meta{ opacity:1; }
@media (hover:none){ .message .message-meta{ opacity:1; } }   /* 触屏兜底 */
```

### 5.5 `event-line` → 活动摘要行（⚠️ 这是最容易做错的地方）

**不要再把每条工具记录做成卡片。** 真机是「一行 21px 小字 + 点击逐层展开」，细节见
`spec/activity-components.md`。三层结构：

```
轮次
├─ 活动摘要行     21px 一行字，如「已读取文件运行了命令」
│   └─ 详情容器   padding 12px 0 0 24px, gap 12px
│       └─ 逐项摘要行   又是 21px 一行
│           └─ 详情容器  padding 8px 0 4px 24px, gap 8px
│               └─ 命令卡  到这里才是卡片
```

摘要行规格（**无边框、无背景、无圆角**）：

```css
.event-line > summary{
  display: inline-flex; align-items: center; gap: 4px;
  height: 21px; padding: 0;
  font-size: 14px; line-height: 21px; font-weight: 430;
  color: var(--app-color-text-foreground-tertiary);   /* rgba(13,13,13,.495) */
  background: none; border: 0; border-radius: 0;
  transition: color var(--transition-duration-basic) var(--ease-out);
}
.event-line > summary:hover{ color: var(--color-text); }   /* #0d0d0d */

/* 图标 16×16，不是 40×40 */
.event-line > summary svg{ width: 16px; height: 16px; flex: none; }

/* 去掉 details 的原生三角 */
.event-line > summary::-webkit-details-marker{ display: none; }
.event-line > summary{ list-style: none; }
```

详情容器：

```css
.event-line .event-detail{
  padding: 12px 0 0 24px;      /* 深层嵌套时用 8px 0 4px 24px */
  display: flex; flex-direction: column; gap: 12px;
  border: 0; background: none;
  font-size: 14px; line-height: 21px;
}
```

命令卡（只有展开到底才出现）：

```css
.command-card{
  border: 0.8px solid rgba(13, 13, 13, 0.118);   /* border-strong，注意不是 .049 */
  border-radius: 12.5px;                          /* rounded-lg，不是 15px */
  background: rgba(13, 13, 13, 0.055);            /* bg-secondary-soft-alpha */
  overflow: hidden;
  display: flex; flex-direction: column;
}
.command-card > header{ padding: 4px 8px; font-size: 13px; color: rgba(13,13,13,.495); }
.command-card .cmd{ padding: 8px 8px 0; font-family: var(--font-mono); font-size: 13px;
                    white-space: pre-wrap; word-break: break-word;
                    display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.command-card .cmd::before{ content: "$ "; color: rgba(13,13,13,.495); margin-inline-end: 1ch; }
.command-card .out{ max-height: 144px; overflow: auto; padding: 8px;
                    font-family: var(--font-mono); font-size: 13px; font-weight: 500; white-space: pre; }
```

摘要文案用真机原话（见 `spec/activity-components.md` §5）：`运行了命令` / `编辑了文件` / `调用了一个工具` /
`已读取文件` / `已搜索网页` / `上下文已自动压缩` / `已创建聊天`。
**多段拼接不加分隔符**。

