.approval-details > summary:hover { color: var(--color-text); }
.approval-details summary svg { width: 14px; height: 14px; }
.approval-details[open] { grid-column: 1 / -1; }
.approval-details dl { margin: 8px 0; }
.approval-card .button-row { grid-column: 2; justify-content: flex-end; align-self: center; margin: 0; }

/* Settings replaces the workspace panel, with the native grouped navigation. */
.settings-view { display: grid; grid-template-columns: 288px minmax(0,1fr); min-width: 0; min-height: 0; margin: 0 4px 4px 0; }
.settings-nav { display: flex; flex-direction: column; gap: 16px; min-height: 0; width: 288px; padding: 12px 8px 16px; overflow: auto; border-radius: 12px 0 0 12px; background: var(--color-sidebar-surface); }
.settings-nav-header { display: flex; align-items: center; justify-content: space-between; flex: none; height: 26px; padding-inline: 8px; }
.settings-page-title { margin: 0; font-size: 20px; line-height: 26px; font-weight: 500; }
.settings-back { display: grid; place-items: center; width: 28px; height: 28px; padding: 6px; border: 0; border-radius: 7.5px; background: none; color: var(--muted); }
.settings-back:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.settings-search { display: flex; align-items: center; gap: 8px; height: 34px; flex: none; margin-top: -8px; padding: 6px 12px; border: 1px solid transparent; border-radius: 18px; background: var(--color-background-nav-active); color: var(--muted); }
.settings-search:focus-within { border-color: var(--color-border-strong); background: var(--app-color-background-surface); }
.settings-search svg { flex: none; width: 16px; height: 16px; }
.settings-search input { width: 100%; min-width: 0; padding: 0; border: 0; outline: 0; background: none; font-size: 13px; line-height: 20px; }
.settings-search input::-webkit-search-cancel-button, .quest-search input::-webkit-search-cancel-button { -webkit-appearance: none; }
.settings-search-clear { display: grid; place-items: center; width: 22px; height: 22px; flex: none; padding: 0; border: 0; border-radius: 50%; background: none; color: var(--muted); }
.settings-search-clear:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.settings-nav-section { display: flex; flex-direction: column; gap: 1px; }
.settings-nav-group { margin: 0; padding: 8px 8px 4px; color: var(--muted); font-size: 14px; line-height: 21px; font-weight: 500; }
.settings-nav-item { display: flex; align-items: center; gap: 8px; width: 100%; height: 30px; padding: 5px 8px; border: 0; border-radius: 12.5px; background: none; text-align: start; font-size: 13px; line-height: 18.5714px; }
.settings-nav-item:hover, .settings-nav-item.active { background: var(--color-background-secondary-ghost-hover); }
.settings-nav-icon { flex: none; color: var(--color-text-secondary); }
.settings-content { min-width: 0; min-height: 0; padding: 24px 32px; overflow: auto; border-left: 1px solid var(--color-border); background: var(--app-color-background-surface); }
.settings-content-inner { position: relative; width: 100%; max-width: 760px; margin-inline: auto; }
.settings-title { margin: 0 40px 12px 0; font-size: 28px; line-height: 33.6px; font-weight: 500; }
.general-settings { display: flex; flex-direction: column; gap: 40px; padding-top: 24px; }
.settings-block-heading { margin: 0 0 16px; font-size: 14px; line-height: 21px; font-weight: 500; }
.settings-group, .settings-section { overflow: hidden; border: .8px solid var(--color-border-strong); border-radius: 12.5px; }
.settings-section + .settings-section { margin-top: 28px; }
.settings-section-title { margin: 0; padding: 16px 16px 4px; font-size: 14px; line-height: 22px; font-weight: 500; }
.settings-section > .notice { margin: 10px 16px 16px; }
.settings-row { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); }
.settings-group > .settings-row:last-child, .settings-section > .settings-row:last-child { border-bottom: 0; }
.settings-row-text { min-width: 0; flex: 1; }
.settings-row-label { font-size: 13px; line-height: 18px; font-weight: 500; }

