// Static server for the interactive ChatGPT Desktop frontend replica.
// usage: node app/server.js [port]
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname);
const PUBLIC = path.join(ROOT, 'public');
const DATA = path.join(ROOT, 'data');
const ASSETS = path.resolve(ROOT, '..', 'mirror', 'webview', 'assets');
const PORT = Number(process.argv[2] || 8890);

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
  '.webp': 'image/webp', '.avif': 'image/avif', '.gif': 'image/gif', '.ico': 'image/x-icon',
  '.woff': 'font/woff', '.woff2': 'font/woff2', '.ttf': 'font/ttf', '.otf': 'font/otf',
  '.wasm': 'application/wasm', '.mp4': 'video/mp4', '.webm': 'video/webm',
  '.wav': 'audio/wav', '.ogg': 'audio/ogg', '.txt': 'text/plain; charset=utf-8',
};

function send(res, code, type, body) {
  res.writeHead(code, {
    'content-type': type,
    'content-length': Buffer.byteLength(body),
    'cache-control': 'no-store',
    'access-control-allow-origin': '*',
  });
  res.end(body);
}

function serveFile(res, file, fallbackIndex) {
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) {
    if (fallbackIndex) {
      const idx = path.join(PUBLIC, 'index.html');
      return send(res, 200, MIME['.html'], fs.readFileSync(idx));
    }
    return send(res, 404, 'text/plain; charset=utf-8', 'not found');
  }
  const type = MIME[path.extname(file).toLowerCase()] || 'application/octet-stream';
  send(res, 200, type, fs.readFileSync(file));
}

const server = http.createServer((req, res) => {
  try {
    let p = decodeURIComponent((req.url || '/').split('?')[0]);

    if (p === '/' || p === '') p = '/index.html';

    if (p.startsWith('/assets/')) {
      return serveFile(res, path.join(ASSETS, p.slice('/assets/'.length)));
    }
    if (p.startsWith('/data/')) {
      return serveFile(res, path.join(DATA, p.slice('/data/'.length)));
    }
    if (p.startsWith('/partials/') || p.endsWith('.js') || p.endsWith('.css') || p.endsWith('.html')) {
      return serveFile(res, path.join(PUBLIC, p), !p.includes('.'));
    }
    return serveFile(res, path.join(PUBLIC, p), true);
  } catch (e) {
    send(res, 500, 'text/plain; charset=utf-8', String(e));
  }
});

server.listen(PORT, '127.0.0.1', () => {
  console.log(`ChatGPT Desktop replica → http://127.0.0.1:${PORT}/`);
  console.log(`  public: ${PUBLIC}`);
  console.log(`  data  : ${DATA}`);
  console.log(`  assets: ${ASSETS}`);
});
