const settingsState = { section: 'general' };

function renderSettings() {
  const host = $('#settings-view');
  if (!host) return;

  const navHtml = SETTINGS_NAV.map(g => `
    <div class="flex flex-col gap-px">
      <div class="block px-2 pb-1 pt-2 text-default" style="font-size:14px;line-height:21px;font-weight:500;color:rgba(13,13,13,.494)">${esc(g.group)}</div>
      ${g.items.map(it => `
        <button type="button" data-section="${it.id}"
          class="flex w-full items-center gap-2 overflow-hidden text-start transition-colors duration-basic ease-out"
          style="height:30px;padding:5px 8px;border-radius:12.5px;font-size:13px;line-height:18.5714px;font-weight:400;${settingsState.section === it.id ? 'background:rgba(13,13,13,.055)' : ''}"
          data-nav="${it.id}">${esc(it.label)}</button>`).join('')}
    </div>`).join('');

  const body = SETTINGS_BODY[settingsState.section] || SETTINGS_BODY.general;

  host.innerHTML = `
    <div class="flex min-h-0 flex-1">
      <div class="flex min-h-0 shrink-0 flex-col" style="width:288px">
        <div class="flex items-center px-2 pb-2 pt-3">
          <h1 class="text-default heading-xl" style="font-size:20px;line-height:26px;font-weight:500">设置</h1>
